(() => {
  const root=document.getElementById('app');
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pct=n=>`${Math.round(n)}%`,masteryTier=n=>n<20?'Новичок':n<40?'Ученик':n<65?'Опытный':n<85?'Ветеран':'Мастер',itemName=(s,ref)=>{const id=s.inventory.find(item=>item.instanceId===ref)?.id||ref;return s.items[id]?.name||'Пусто';};
  const itemIconPath=item=>`assets/sprites/item-icons/${esc(item?.icon||window.ZoneRPGItems.iconFallback(item||{}))}.svg`;
  const itemIcon=(item)=>`<span class="item-symbol type-${esc(item.type)}"><img class="item-icon" src="${itemIconPath(item)}" alt="" loading="lazy" decoding="async"></span>`;
  const mapPos={"northOutpost":[12,8],"pripyat":[31,8],"chNpp":[50,8],"mirrorLake":[69,8],"anomalyRidge":[88,8],"redforest":[12,25],"militaryDepot":[31,25],"dutyFort":[50,25],"yantar":[69,25],"swamp":[88,25],"warehouses":[12,42],"freeCamp":[31,42],"researchCamp":[50,42],"underground":[69,42],"machineYard":[88,42],"wild":[12,59],"floodplain":[31,59],"agro":[50,59],"garbage":[69,59],"darkvalley":[88,59],"quarry":[12,76],"greenhouse":[31,76],"deadVillage":[50,76],"southTunnel":[69,76],"railway":[88,76],"radioHill":[12,93],"rookie":[31,93],"cordon":[50,93],"checkpoint":[69,93]};
  function button(action,label,cls='',value='',extra=''){return `<button class="${cls}" type="button" data-action="${action}"${value!==''?` data-value="${esc(value)}"`:''}${extra!==''?` data-extra="${esc(extra)}"`:''}>${label}</button>`;}
  function itemFacts(item){const e=item.effect||{},facts=[];if(item.type==='food'&&e.hunger)facts.push(`Восстанавливает голод: +${Math.abs(e.hunger)}%`);if(item.type==='drink'&&e.thirst)facts.push(`Восстанавливает жажду: +${Math.abs(e.thirst)}%`);if(item.type==='medicine'&&e.health)facts.push(`Лечит: +${e.health} HP`);if(item.type==='medicine'&&e.radiation)facts.push(`Снижает радиацию: ${Math.abs(e.radiation)}%`);if(item.type==='weapon'&&item.weaponId){const w=window.ZoneRPGItems.weapons[item.weaponId];facts.push(`${w.damage} урона · точность ${pct(w.accuracy*100)}${w.magazine?` · магазин ${w.magazine}`:''}`);if(w.traitText)facts.push(w.traitText);}if(['armor','headgear'].includes(item.type)){if(e.protection)facts.push(`Защита: ${pct(e.protection*100)}`);if(e.radResist)facts.push(`Сопротивление радиации: ${pct(e.radResist*100)}`);}if(item.type==='backpack'&&e.maxWeight)facts.push('Грузоподъёмность: +'+e.maxWeight+' кг');if(item.type==='artifact'){if(e.protection)facts.push(`Защита: +${pct(e.protection*100)}`);if(e.radResist)facts.push(`Сопротивление радиации: +${pct(e.radResist*100)}`);if(e.maxWeight)facts.push(`Грузоподъёмность: ${e.maxWeight>0?'+':''}${e.maxWeight} кг`);if(e.maxHealth)facts.push(`Максимальное здоровье: ${e.maxHealth>0?'+':''}${e.maxHealth} HP`);if(e.maxStamina)facts.push(`Максимальная выносливость: ${e.maxStamina>0?'+':''}${e.maxStamina}`);if(e.radPerTrip)facts.push(`Радиация за переход: +${e.radPerTrip}%`);}return facts.length?`${item.description} ${facts.join(' · ')}`:item.description;}
  function disabledButton(label,reason=''){return '<button type="button" class="tiny-button" disabled title="'+esc(reason)+'">'+esc(label)+'</button>';}
  function head(s){const p=s.player,loc=s.locations[p.location],weapon=s.activeWeapon?.weapon,mag=s.activeWeapon?.magazine||0,reserve=s.activeWeapon?.reserve||0;return `<header class="topbar"><a class="brand" href="#" data-action="home"><span class="brand-mark">Z</span>ZONE<span class="brand-dim">RPG</span></a><div class="top-location"><small>ТЕКУЩИЙ СЕКТОР · ${esc(s.timeLabel.toLocaleUpperCase('ru-RU'))}</small><strong>${esc(loc.name)}</strong></div></header><div class="status-strip"><div class="stat-chip"><span>♥ ЗДОРОВЬЕ</span><strong>${Math.ceil(p.health)} / ${s.stats.maxHealth}</strong><i><b class="health-fill" style="width:${pct(p.health/(s.stats.maxHealth)*100)}"></b></i></div><div class="stat-chip"><span>⚡ ВЫНОСЛИВОСТЬ</span><strong>${Math.ceil(p.stamina)} / ${s.stats.maxStamina}</strong><i><b class="stamina-fill" style="width:${pct(p.stamina/(s.stats.maxStamina)*100)}"></b></i></div><div class="stat-chip"><span>🍖 ГОЛОД</span><strong>${pct(p.hunger)}</strong><i><b class="hunger-fill" style="width:${pct(p.hunger)}"></b></i></div><div class="stat-chip"><span>💧 ЖАЖДА</span><strong>${pct(p.thirst)}</strong><i><b class="thirst-fill" style="width:${pct(p.thirst)}"></b></i></div><div class="stat-chip"><span>☢ РАДИАЦИЯ</span><strong>${pct(p.radiation)}</strong><i><b class="rad-fill" style="width:${pct(p.radiation)}"></b></i></div><div class="stat-chip money-chip"><span>НАЛИЧНЫЕ</span><strong>₽ ${p.money.toLocaleString('ru-RU')}</strong></div><div class="stat-chip level-chip"><span>УРОВЕНЬ ${p.rank}</span><strong>${p.xp} / ${s.xpForNextLevel} XP</strong><i><b style="width:${pct(p.xp/s.xpForNextLevel*100)}"></b></i></div><div class="stat-chip weapon-chip"><span>В РУКАХ</span><strong>${esc(s.activeWeapon?.item.name||'Без оружия')}</strong><small>${weapon?.ammoType?`${mag} / ${reserve}`:weapon?'ближний бой':'—'}</small></div></div>`;}
  function nav(s){if(['menu','background','dead'].includes(s.mode)||s.panelReturn==='menu')return '';const busy=Boolean(s.expedition.active||s.event||s.combat||s.travelTo);return `<nav class="action-dock" aria-label="Основная навигация">${button('panel',window.ZoneRPGI18n.t('map'),'dock-button','map','⌖')}${busy?'<button class="dock-button" disabled title="Сначала завершите текущую встречу или вылазку">⌕ Исследовать</button>':button('explore','Исследовать','dock-button','','⌕')}${button('panel',window.ZoneRPGI18n.t('inventory'),'dock-button',s.combat?'combatItems':'inventory','▣')}${button('panel',window.ZoneRPGI18n.t('character'),'dock-button','character','◉')}${button('panel',window.ZoneRPGI18n.t('quests'),'dock-button','quests','≡')}${button('panel',window.ZoneRPGI18n.t('more'),'dock-button','more','···')}</nav>`;}
  function eventArtFor(e,s){const t=(e.category+' '+e.text).toLocaleLowerCase('ru-RU');if(/кост|огонь|fire|camp/.test(t))return 'fire';if(/аномал|дозим|сигнал детектор|радиац/.test(t))return 'anomaly';if(/труп|тело сталкер|погибш/.test(t))return 'body';if(/склад|арсенал|warehouse/.test(t))return 'warehouse';if(/тоннел|коллектор|подзем|tunnel/.test(t))return 'tunnel';if(/вышк|мачт|tower/.test(t))return 'tower';if(/деревн|дом|хат|village/.test(t))return 'house';if(/контейнер|ящик|груз|crate/.test(t))return 'container';if(/машин|автобус|грузов|кузов/.test(t))return 'abandoned-car';if(/бандит|засад|перекрыл|выстрел|напад/.test(t))return 'abandoned-car';if(/дорог|троп|путь|след/.test(t))return 'road';return 'road';}
  function encounterCue(e){const d=window.ZoneRPGWorld.events.find(x=>x.id===e.id)||e;if(['rare','very_rare','special','unique','legendary'].includes(e.rarity))return '✦ НЕОБЫЧНЫЙ СИГНАЛ';if(d.personalStory)return '◈ ЛИЧНАЯ ИСТОРИЯ';if(d.npcId||e.id.startsWith('npc_story_'))return '◉ РАЗГОВОР';if(/аномал|артефакт/i.test(e.category))return '☢ АНОМАЛИЯ';if((d.stages||[{choices:d.choices}]).some(stage=>stage.choices?.some(c=>c.combat)))return '⚠ ОПАСНОСТЬ';if(/тайник|запас|находк|свёрток/i.test(e.category))return '▣ НАХОДКА';return '⌖ ПОЛЕВАЯ ЗАПИСЬ';}
  function eventCard(s){const e=s.event;if(!e)return '';const flow=e.flow,canReturn=flow?.phase==='result'&&!flow.pending?.nextStage&&!flow.pending?.nextEvent&&flow.origin==='explore'&&s.expedition.active,art=e.art||window.ZoneRPGWorld.events.find(d=>d.id===e.id)?.art||eventArtFor(e,s),history=(flow?.history||[]).slice(-2),r=flow?.flags?.actionRewards||(flow?.flags?.battleJustWon?flow.flags.combatRewards:flow?.rewards);const totalXP=(r?.xp||0)+(flow?.flags?.actionRewards||flow?.flags?.battleJustWon?0:flow?.completionXP||0),hasReward=(flow?.phase==='result'||flow?.flags?.battleJustWon)&&(r||flow.completionXP),reward=hasReward?'<div class="event-rewards"><b>'+(flow?.flags?.actionRewards?'Дополнительно найдено':flow?.flags?.battleJustWon?'Добыча за бой':'ИТОГ ВСТРЕЧИ')+'</b><span>+'+totalXP+' XP</span>'+(r?.money?'<span>+'+r.money+' ₽</span>':'')+((r?.items||[]).map(x=>'<span>+'+(x.qty||1)+' '+esc(s.items[x.id]?.name||x.name||'Предмет')+'</span>').join(''))+'</div>':'';return `<section class="event-card ${s.travelTo?'travel-event':''} ${['rare','very_rare','special','unique','legendary'].includes(e.rarity)?'rare-event':''}"><div class="event-label"><span class="pulse-dot"></span>${s.travelTo?`ДОРОГА · ПУТЬ К ${esc(s.locations[s.travelTo].name.toLocaleUpperCase('ru-RU'))}`:`СОБЫТИЕ · ${esc(e.category.toLocaleUpperCase('ru-RU'))}`}${flow?.stageIndex>=0?` · ЭТАП ${flow.visitedStages?.length||flow.stageIndex+1}`:''}</div><small class="encounter-cue">${esc(encounterCue(e))}</small><img class="event-art" src="${s.people[e.id.slice(10)]?.sprite?'assets/sprites/npc-'+esc(s.people[e.id.slice(10)].sprite)+'.svg':'assets/sprites/scene-'+esc(art)+'.svg'}" alt="Иллюстрация события: ${esc(e.category)}" loading="lazy" decoding="async"><h2 class="event-title">${esc(e.category)}</h2>${window.ZoneRPGWorld.events.find(d=>d.id===e.id)?.npcId?`<p class="npc-scene-label"><img class="npc-scene-portrait" src="assets/sprites/npc-${esc(s.people[window.ZoneRPGWorld.events.find(d=>d.id===e.id).npcId]?.sprite)}.svg" alt="Портрет собеседника">${esc(s.people[window.ZoneRPGWorld.events.find(d=>d.id===e.id).npcId]?.name)} · ${esc(s.people[window.ZoneRPGWorld.events.find(d=>d.id===e.id).npcId]?.role)}</p>`:''}<p class="event-copy">${esc(e.text)}</p>${history.length?`<div class="event-history" aria-label="Предыдущие действия">${history.map(x=>`<span>${esc(x.choice)} · ${esc(x.text)}</span>`).join('')}</div>`:''}${reward}${canReturn&&flow.origin==='explore'?'<p class="event-session">Вылазка: '+esc(s.locations[s.explorationOriginLocationId||s.player.location].name)+' · глубина '+s.explorationSessionDepth+' · '+esc(s.livingView.depth.name)+'. Продолжить: следующий поиск за '+s.expeditionCost+' выносливости. Вернуться: закончить вылазку.</p>':''}${e.choices?.length?`<div class="choice-list ${canReturn?'event-result-actions':''}">${e.choices.map((c,i)=>canReturn&&flow.origin==='explore'&&c.action==='advance'&&s.player.stamina<s.expeditionCost?'<button class="choice-button" disabled>Нет сил · нужно '+s.expeditionCost+' выносливости</button>':button('event',esc(c.label),'choice-button',String(i))).join('')}${canReturn?button('eventReturn','ВЕРНУТЬСЯ','choice-button event-return'):''}</div>`:''}</section>`;}
  function locationScene(s){const loc=s.locations[s.player.location],hasTrader=!!s.shop;return `<section class="scene-card"><div class="scene-kicker"><span>${esc(loc.layout)}</span><span class="danger-pill danger-${Math.min(10,loc.danger)}">РИСК ${loc.danger}/10</span></div><img class="location-header-art" src="assets/sprites/scene-${esc(s.player.location==='chNpp'?'cnpp':window.ZoneRPGZoneData.pois.find(p=>p.location===s.player.location)?.art||combatSceneFor(s))}.svg" alt="Пейзаж сектора"><h1>${esc(loc.name)}</h1><p>${esc(loc.description)}</p><p class="world-readout">Обстановка: ${esc(s.livingView.state)} · ${esc(s.livingView.weather)}</p><div class="scene-details"><span>ФОН ${loc.rad}% · ${esc(s.radStage.toLocaleUpperCase('ru-RU'))}</span><span>МУТАНТЫ ${loc.mutants}%</span><span>БАНДИТЫ ${loc.bandits}%</span></div><div class="scene-actions">${storyLocationHint(s)}${s.zoneView.ready?button('zoneAction','След расследования','secondary-button'):''}${button('panel','Известные места','secondary-button','zonePlaces')}${s.livingView.action?button('livingAction',s.livingView.action,'secondary-button'):''}${button('explore',window.ZoneRPGI18n.t('explore'),'primary-button main-explore','','⌕')}${hasTrader?button('panel',`Торговец · ${esc(s.shop.name)}`,'secondary-button','trade','₽'):''}${s.quests.active.filter(q=>!q.ready&&(q.id==='field_notes'||q.type==='anomaly')&&(q.searchLocation||q.target)===s.player.location).map(q=>questSearchButton(q,s)).join('')}${button('breath','Передохнуть · 1 час','secondary-button')}${loc.camp||hasTrader?button('rest','Отдых у костра · 35 ₽','secondary-button')+button('news','Послушать слухи','secondary-button'):''}${loc.npcs.length?button('panel','Люди поблизости','secondary-button','people','◉'):''}</div><small class="explore-limit">Осмотрено: ${s.explores[s.player.location]||0} · Переходы меняют время, голод, жажду и выносливость.</small></section>`;}
  function weatherLine(s){const weather=['низкие тучи','сухой ветер','мелкий дождь','туман'][s.player.trips%4];const hour=s.player.time<5||s.player.time>=21?'Ночь':s.player.time<10?'Утро':s.player.time<17?'День':'Вечер';return `<div class="ambient-line"><span>${esc(hour)} · ${weather}</span><span>рейд №${String(s.player.trips+1).padStart(2,'0')}</span><span>выносливость влияет на риск</span></div>`;}
  function logbox(s){return `<section class="log-panel"><div class="section-heading"><span>ЗАПИСИ КПК</span><small>последние сообщения</small></div><div class="log-lines">${s.log.slice(-5).reverse().map((x,i)=>`<p class="${i===0?'latest':''}">${esc(x)}</p>`).join('')}</div></section>`;}
  function routeTeaser(s){return `<section class="route-teaser"><div><span class="section-heading">СЛЕДУЮЩИЙ ШАГ</span><p>Доступно направлений: <b>${s.routes.filter(x=>x.open).length}</b></p></div><small>Направления — в разделе «Карта» нижней панели.</small></section>`;}
  function gameScreen(s){const body=s.combat?combat(s):s.event?eventCard(s):locationScene(s);return `<div class="game-shell">${head(s)}<main class="game-main"><div class="primary-column">${weatherLine(s)}${tutorialCard(s)}${body}${!s.combat&&!s.event?routeTeaser(s):''}${logbox(s)}</div><aside class="rail"><section class="rail-card"><div class="section-heading"><span>СНАРЯЖЕНИЕ</span></div><div class="gear-row"><span>ОРУЖИЕ</span><strong>${esc(itemName(s,s.equipment.weapon))}</strong><small>${s.weapons[s.items[s.equipment.weapon]?.weaponId]?.damage||0} урона · точность ${pct((s.weapons[s.items[s.equipment.weapon]?.weaponId]?.accuracy||0)*100)}</small></div><div class="gear-row"><span>БРОНЯ</span><strong>${esc(itemName(s,s.equipment.armor))}</strong><small>Защита ${pct(s.passive.protection*100)} · фон −${pct(s.passive.radResist*100)}</small></div><div class="artifact-slots">${[0,1,2,3].map(i=>`<span>${s.equipment.artifacts[i]?esc(itemName(s,s.equipment.artifacts[i])):'пустой слот'}</span>`).join('')}</div></section><section class="rail-card quest-highlight"><div class="section-heading"><span>ТЕКУЩЕЕ ДЕЛО</span></div>${s.quests.active.length?s.quests.active.slice(0,2).map(q=>`<div class="mini-quest"><strong>${esc(q.title)}</strong><small>${esc(q.text)}</small></div>`).join(''):'<p class="quiet">Пока нет поручений. Поговори с местными.</p>'}</section><section class="rail-card zone-note"><span>☢</span><p>Зона отвечает на каждый шаг. Переносимый вес: <b>${s.weight.toFixed(1)}/${s.capacity} кг</b>.</p></section></aside></div>${nav(s)}</div>`;}
  function combatSceneFor(s){const id=s.player.location;if(id==='swamp')return 'swamp';if(['redforest','wild'].includes(id))return 'forest';if(['underground','southTunnel','chNpp'].includes(id))return 'tunnel';if(['warehouses','militaryDepot','machineYard'].includes(id))return id==='warehouses'?'warehouse':'industrial';if(['rookie','deadVillage'].includes(id))return 'village';if(['cordon','garbage','checkpoint','railway'].includes(id))return 'road';if(['anomalyRidge','yantar'].includes(id))return 'industrial';return 'camp';}
  function combat(s){const c=s.combat,e=c.enemy,p=s.player,active=s.activeWeapon,weaponId=active?.id,weapon=active?.weapon||{name:'Без оружия',ammoType:null,magazine:0,damage:0,accuracy:0},ammo=active?.reserve||0,max=e.maxHp||e.hp,stamina=s.stats.maxStamina;return '<section class="combat-card combat-arena" data-background="'+combatSceneFor(s)+'" data-enemy="'+esc(e.visual||c.type)+'"><div class="combat-kicker"><span>КОНТАКТ · ХОД '+c.turn+'</span><span class="danger-pill">ОПАСНОСТЬ</span></div><div class="combat-opponent"><div class="combat-title-row"><div><small>ЦЕЛЬ · '+esc(c.status||'В БОЮ')+' · '+(c.distance==='far'?'ДАЛЬНЯЯ ДИСТАНЦИЯ':'БЛИЖНЯЯ ДИСТАНЦИЯ')+'</small><p class="combat-hint">'+esc(e.windup?'Тяжёлый противник: следи за замахом.':e.evasion?'Подвижная цель: прицеливание повышает шанс попадания.':window.ZoneRPGItems.weapons[e.weapon]?.ammoType?'Вооружённая цель: укрытие смягчит ответный огонь.':'Противник сближается; нож требует риска.')+'</p><h1>'+esc(e.name)+'</h1><p class="combat-note">'+esc(c.intro||e.description||'Противник не отступает. Следи за дистанцией и боезапасом.')+'</p>'+((s.zoneView.knowledge.mutants[c.type]||0)>=3?'<p class="combat-hint">ИЗУЧЕН: защита '+Math.round((e.armor||0)*100)+'%, уклонение '+Math.round((e.evasion||0)*100)+'%. '+(e.windup?'После замаха ожидай тяжёлый удар.':'Прицеливание помогает удержать быструю цель.')+'</p>':'')+'</div><div class="enemy-health"><strong>♥ '+Math.max(0,e.hp)+' / '+max+' HP</strong><i><b style="width:'+pct(Math.max(0,e.hp)/max*100)+'"></b></i></div></div><div class="sprite-stage" style="background-image:url(assets/sprites/combat-'+combatSceneFor(s)+'.svg)"><img class="enemy-sprite" src="assets/sprites/enemy-'+esc(e.visual||c.type)+'.svg" alt="'+esc(e.name)+'"><span class="sprite-caption">'+esc(e.name.toLocaleUpperCase('ru-RU'))+'</span></div></div><div class="combat-player"><img class="player-sprite" src="assets/sprites/player-stalker.svg" alt="Сталкер"><div class="player-combat-stats"><strong>ТЫ · '+Math.ceil(p.health)+' / '+s.stats.maxHealth+' HP</strong><i><b class="health-fill" style="width:'+pct(p.health/s.stats.maxHealth*100)+'"></b></i><strong>ВЫНОСЛИВОСТЬ · '+Math.ceil(p.stamina)+' / '+stamina+'</strong><i><b class="stamina-fill" style="width:'+pct(p.stamina/stamina*100)+'"></b></i><span>ЗАЩИТА · '+Math.round(s.stats.protection*100)+'%'+(c.aimed?' · ПРИЦЕЛ ГОТОВ':'')+'</span><span>ОРУЖИЕ · '+esc(weapon.name)+' · '+(weapon.ammoType?(active?.magazine||0)+'/'+weapon.magazine+' · запас '+ammo:active?'ближний бой':'без оружия')+'</span><small>'+weapon.damage+' урона · точность '+pct(weapon.accuracy*100)+' · '+esc(active?weapon.range||'ближний бой':'атака недоступна')+'</small></div></div><div class="combat-actions">'+(active?(!weapon.ammoType||(active.magazine||0)>0?button('attack',window.ZoneRPGI18n.t(weapon.ammoType?'fire':'melee'),'primary-button combat-fire'):disabledButton('Магазин пуст · перезаряди','Нет патронов в магазине')):disabledButton('Нужно оружие','Экипируй нож или огнестрельное оружие'))+(weapon.ammoType?((active?.magazine||0)>=weapon.magazine?disabledButton('Магазин полон','Перезарядка не нужна'):ammo>0?button('reload','ПЕРЕЗАРЯДКА','secondary-button'):disabledButton('Нет запасных патронов','Можно сменить оружие')):'')+(weapon.ammoType?(p.stamina>=8?button('aim','ПРИЦЕЛИТЬСЯ · 8 сил','secondary-button'):disabledButton('Прицеливание · нужно 8 сил','Недостаточно выносливости')):'')+(p.stamina>=5?button('defend','УКРЫТЬСЯ · 5 сил','secondary-button'):disabledButton('Укрыться · нужно 5 сил','Недостаточно выносливости'))+button('combat','ИСПОЛЬЗОВАТЬ ПРЕДМЕТ','secondary-button','items')+button('combat','СМЕНИТЬ ОРУЖИЕ','secondary-button','weapons')+(c.retreatLocked?disabledButton('Путь отрезан','Обязательный бой'):button('flee','ОТСТУПИТЬ · '+Math.round(s.retreatChance)+'%','danger-button'))+'</div><div class="combat-log" aria-live="polite">'+c.log.slice(-5).map(x=>'<p>'+esc(x)+'</p>').join('')+'</div></section>';}  function countAmmo(s,id){return id?s.inventory.find(x=>x.id===id)?.qty||0:0;}
  function overlay(title,inner,close=true,sub='КПК · ZONE RPG'){return `<div class="overlay-shade"><section class="panel-window" role="dialog" aria-modal="false"><header class="panel-window-head"><div><small>${esc(sub)}</small><h2>${esc(title)}</h2></div>${close?button('close','×','close-button'):''}</header>${inner}</section></div>`;}
  function inventory(s){const slots=['primary','sidearm','melee','armor','head','backpack','detector'],weapons=['primary','sidearm','melee'];const rows=s.inventory.map((x,i)=>{const it=s.items[x.id],ref=x.instanceId||x.id,slot=it.slot,equipped=slots.some(key=>s.equipment[key]===ref)||Boolean(x.instanceId&&s.equipment.artifacts.includes(x.instanceId)),current=s.equipment.activeWeaponSlot===slot&&equipped,wp=it.type==='weapon'?s.weapons[it.weaponId]:null,mag=s.magazines[x.id]||0,reserve=wp?.ammoType?countAmmo(s,wp.ammoType):0;return '<article class="item-row-card">'+itemIcon(it)+'<div class="item-info"><strong>'+esc(it.name)+(equipped?'<em>ЭКИПИРОВАНО</em>':'')+'</strong><p>'+esc(itemFacts(it))+'</p><small>'+it.weight+' кг · '+it.price.toLocaleString('ru-RU')+' ₽ · ×'+x.qty+(wp?.ammoType?' · магазин '+mag+'/'+wp.magazine+' · запас '+reserve:wp?' · ближний бой':'')+'</small></div><div class="item-row-actions">'+(slot?button(equipped?'unequipSlot':'equipGear',equipped?'Снять':'Надеть','tiny-button',equipped?slot:ref):'')+(slot&&equipped&&weapons.includes(slot)&&!current?button('switchWeapon','В руки','tiny-button',slot):'')+(wp?.ammoType?(mag>=wp.magazine?disabledButton('Магазин полон','Перезарядка не требуется'):reserve<=0?disabledButton('Нет патронов','Нет подходящих боеприпасов'):button('reload','Перезарядить','tiny-button',ref)): '')+(it.type==='artifact'?(equipped||s.equipment.artifacts.length<4?button('artifact',equipped?'Снять':'Надеть','tiny-button',ref):disabledButton('Слоты заняты','Сначала сними один из четырёх артефактов')):'')+(['medicine','food','drink'].includes(it.type)?button('use','Использовать','tiny-button',String(i)):'')+(equipped?disabledButton('Сначала снять','Нельзя выбросить экипированный предмет'):button('drop','Выбросить','tiny-button',ref))+'</div></article>';}).join('')||'<p class="quiet empty">Рюкзак пуст.</p>';return overlay('Рюкзак','<div class="panel-summary '+(s.weight>s.capacity?'weight-warning':'')+'">'+s.weight.toFixed(1)+' / '+s.capacity+' кг · предел с экипировкой '+s.stats.maxCarryWeight.toFixed(0)+' кг'+(s.weight>s.capacity?' · ПЕРЕГРУЗ':'')+'</div><div class="item-list">'+rows+'</div><div class="panel-footnote">Магазин каждого оружия сохраняется отдельно. Перезарядка доступна до боя; снятие рюкзака не удаляет предметы.</div>');}  function mapRadiation(s,id,risk){
    const base=s.locations[id].rad,extra=window.ZoneRPGLiving.modifier(s,'radiation',id);
    const format=value=>Number(value.toFixed(2)).toLocaleString('ru-RU');
    return '<small class="map-radiation" title="Базовый фон локации'+(extra?'; временная прибавка к облучению за поиск до защиты экипировки':'')+'">Риск '+esc(risk)+'/10 · Фон '+esc(format(base))+'%'+(extra?' (+'+esc(format(extra))+'/поиск)':'')+'</small>';
  }
  function mapPanel(s){const blocked=Boolean(s.expedition.active||s.event||s.combat||s.travelTo),reason=s.expedition.active?'Нельзя перейти в другую локацию во время вылазки.':'Сначала завершите текущую встречу.';const nodes=s.map.map(n=>{const pos=mapPos[n.id]||[50,50];return '<button class="map-node '+(n.current?'current ':'')+(n.visited?'visited ':'')+(n.open?'open':'locked')+'" style="left:'+pos[0]+'%;top:'+pos[1]+'%" data-action="travel" data-value="'+esc(n.id)+'" '+(blocked?'disabled title="'+esc(reason)+'"':n.open?'':'disabled')+'><b>'+esc(n.known||n.id==='chNpp'?n.name:'???')+(n.current?'<span class="map-current-label"> · ты здесь</span>':'')+'</b>'+(n.known?mapRadiation(s,n.id,n.danger):'<small>'+(n.id==='chNpp'&&!n.open?'МАРШРУТ НЕИЗВЕСТЕН':'НЕИЗВЕСТНО')+'</small>')+(n.known?'<small class="map-faction">'+esc([...new Set((s.locations[n.id].npcs||[]).map(id=>s.factions[s.people[id]?.faction]?.name).filter(Boolean))].slice(0,2).join(' · '))+'</small>':'')+'</button>';}).join('');const paths=s.mapEdges.filter(e=>s.map.find(n=>n.id===e.from)?.known&&s.map.find(n=>n.id===e.to)?.known).map(e=>{const p=mapPos[e.from],q=mapPos[e.to];return p&&q?'<line data-from="'+esc(e.from)+'" data-to="'+esc(e.to)+'" x1="'+p[0]+'" y1="'+p[1]+'" x2="'+q[0]+'" y2="'+q[1]+'" '+(!e.twoWay?'marker-end="url(#route-arrow)" ':'')+'class="map-path '+(e.secret?'secret ':'')+((e.from===s.player.location||e.to===s.player.location)?'adjacent ':'')+'"/>':'';}).join('');return overlay('Схема Зоны','<p class="map-conditions">'+esc(s.livingView.state)+' · '+esc(s.livingView.weather)+'</p><p class="panel-intro">Сектор: <b>'+esc(s.locations[s.player.location].name)+'</b>. Выбирай соседний открытый сектор.</p>'+(blocked?'<p class="map-travel-warning" role="status">'+esc(reason)+'</p>':'')+'<div class="zone-map"><div class="map-content"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><defs><marker id="route-arrow" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="4" markerHeight="4" orient="auto"><path d="M0 0L10 5L0 10z" fill="currentColor"/></marker></defs>'+paths+'</svg>'+nodes+'</div></div><div class="map-legend"><span><i class="current-dot"></i>Ты здесь</span><span><i class="known-dot"></i>Одна линия — двусторонняя дорога</span><span><i class="locked-dot"></i>Закрытая зона</span></div><div class="route-list"><h3>ДОРОГИ ОТ СЕКТОРА</h3>'+s.routes.map(r=>'<div class="route-row"><span><b>'+esc(r.name)+'</b><small>Риск '+r.danger+'/10 · фон '+r.rad+'%</small></span>'+(blocked?disabledButton('Переход недоступен',reason):r.open?button('travel','Отправиться','tiny-button',r.id):disabledButton('Закрыто',r.reason||'Путь пока недоступен'))+'</div>').join('')+'</div>');}
  function questSearchButton(q,s){const label=q.id==='field_notes'?'Искать документы':'Искать следы аномалий';return s.event||s.combat||s.expedition.active?disabledButton(label,'Сначала завершите встречу или вернитесь из вылазки'):button('questSearch',label,'secondary-button',q.id);}
  function questsPanel(s){const active=s.quests.active.map(q=>'<article class="quest-card"><div class="quest-mark">⌖</div><div><strong>'+esc(q.title)+'</strong><p class="quest-status">'+esc(q.status)+'</p><p>'+esc(q.text)+'</p><p class="quest-origin">Получено: '+esc(s.locations[q.acceptedAtLocation]?.name||'неизвестно')+' · Заказчик: '+esc(s.people[q.giver]?.name||'неизвестно')+' · Сдача: '+esc(q.turnInLocations.map(id=>s.locations[id].name).join(', '))+'</p><small>'+(q.type==='route'?(q.step?'ВЕРНИСЬ: '+esc(s.locations[q.returnTo].name):'ДОЙДИ: '+esc(s.locations[q.target].name)):q.type==='visit'?'ДОЙДИ: '+esc(s.locations[q.target].name):'ПРОГРЕСС · '+(q.progress||0)+(q.count?' / '+q.count:''))+' · НАГРАДА '+q.reward+' ₽</small></div>'+(!q.ready&&(q.id==='field_notes'||q.type==='anomaly')&&(q.searchLocation||q.target)===s.player.location?questSearchButton(q,s):q.type==='research'&&!q.ready&&q.target===s.player.location?button('researchQuest','Провести исследование','tiny-button',q.id):q.canTurnIn?button('turnIn','Сдать','tiny-button',q.id):disabledButton(q.status,q.ready?'Вернись к заказчику':'Выполни условия поручения'))+'</article>').join('')||'<p class="quiet">Активных заданий нет.</p>';const avail=s.quests.available.map(q=>'<article class="quest-card offer"><div><strong>'+esc(q.title)+'</strong><p>'+esc(q.text)+'</p><small>НАГРАДА '+q.reward+' ₽</small></div>'+button('acceptQuest','Принять','tiny-button',q.id)+'</article>').join('')||'<p class="quiet">Новых поручений в этом секторе нет.</p>';return overlay('Журнал заданий',button('panel','Личная история · '+esc(s.storyView.title),'secondary-button','personalStory')+'<h3>АКТИВНЫЕ</h3><div class="quest-list">'+active+'</div><h3>ПОРУЧЕНИЯ В ЭТОМ СЕКТОРЕ</h3><div class="quest-list">'+avail+'</div><h3>ВЫПОЛНЕНО · '+s.quests.completed.length+'</h3><p class="quiet">'+(s.quests.completed.map(q=>esc(q.title)+' · '+q.status).join(' · ')||'Пока пусто.')+'</p>');}
  function character(s){const p=s.player,entries=Object.entries(s.factions).map(([id,f])=>`<div class="faction-row"><span>${esc(f.name)}</span><div><i><b style="width:${pct((s.reputation[id]+100)/2)};background:${f.color}"></b></i></div><strong>${s.reputation[id]>0?'+':''}${s.reputation[id]}</strong></div>`).join(''),labels={primary:'Основное оружие',sidearm:'Пистолет',melee:'Ближний бой',armor:'Броня',head:'Голова',backpack:'Рюкзак',detector:'Детектор'},slots=Object.entries(labels).map(([slot,label])=>{const ref=s.equipment[slot],item=s.inventory.find(x=>x.instanceId===ref)||s.inventory.find(x=>x.id===ref),name=item?s.items[item.id].name:'Пусто';return `<div class="gear-select"><span><small>${label}</small><br>${esc(name)}</span>${item?button('unequipSlot','Снять','tiny-button',slot):'<span class="quiet">—</span>'}${['primary','sidearm','melee'].includes(slot)&&item?(s.equipment.activeWeaponSlot===slot?disabledButton('В руках'):button('switchWeapon','В руки','tiny-button',slot)):''}</div>`}).join(''),gear=s.inventory.filter(x=>s.items[x.id].slot).map(x=>{const it=s.items[x.id],ref=x.instanceId||x.id;return `<div class="gear-select"><span>${esc(it.name)} · ${labels[it.slot]}</span>${s.equipment[it.slot]===ref?button('unequipSlot','Снять','tiny-button',it.slot):button('equipGear','Экипировать','tiny-button',ref)}</div>`}).join('')||'<p class="quiet">Снаряжения нет.</p>',arts=s.inventory.filter(x=>s.items[x.id]?.type==='artifact').map(x=>{const ref=x.instanceId||x.id,on=s.equipment.artifacts.includes(ref);return `<div class="gear-select"><span>${esc(s.items[x.id].name)} · ${on?'в слоте':'в рюкзаке'}</span>${!on&&s.equipment.artifacts.length>=4?disabledButton('Слоты заняты','Сначала сними один артефакт'):button('artifact',on?'Снять':'В слот','tiny-button',ref)}</div>`}).join('')||'<p class="quiet">Артефактов пока нет.</p>';return overlay('Персонаж',`<div class="character-summary"><img class="profile-sprite" src="assets/sprites/player-stalker.svg" alt="Пиксель-арт сталкера"><div class="rank-badge">${String(p.rank).padStart(2,'0')}</div><div><h3>Ранг: ${esc(s.playerRank.name)} · уровень ${p.rank}</h3><p>Подготовка: ${s.playerRank.score} · ${s.playerRank.next?"До «"+esc(s.playerRank.next)+"»: "+(s.playerRank.nextScore-s.playerRank.score):"Высший ранг"}</p><details><summary>Как считается ранг?</summary><p>6 × min(уровень − 1, 30) + 2 × сумма прироста характеристик выше 2 (до 10 на каждую) + 0,8 × среднее мастерство пяти классов. Деньги не влияют.</p></details><p>Предыстория: ${esc(s.backgrounds[s.backgroundId].name)}</p><p class="renown-readout" title="Известность — как широко знают твои дела. Репутация — отношение отдельной группировки.">Известность: ${s.livingView.renown} — ${esc(s.livingView.renownName)}</p><p>Начало пути: ${esc(s.locations[s.startingLocation]?.name||'неизвестно')}</p><p>${p.xp} опыта · ${p.trips} переходов · ${p.kills} побед · найдено ${p.artifacts} артеф.</p><p>Здоровье ${Math.ceil(p.health)} / ${s.stats.maxHealth} · выносливость ${Math.ceil(p.stamina)} / ${s.stats.maxStamina}</p></div></div><h3>РАЗВИТИЕ · +${s.attributePoints} очков</h3><div class="attribute-grid">${Object.entries(s.attributes).map(([key,value])=>`<div class="attribute-row"><strong>${esc(s.attributeInfo[key].name)}</strong><details class="stat-info"><summary aria-label="Описание: ${esc(s.attributeInfo[key].name)}">?</summary><p>${esc(s.attributeInfo[key].description)}</p></details><span>${value}/20</span>${s.attributePoints?button("investAttribute","+","tiny-button",key):""}</div>`).join("")}</div><div class="xp-meter"><span>УРОВЕНЬ ${p.rank} · ${p.xp}/${s.xpForNextLevel} XP</span><i><b style="width:${pct(p.xp/s.xpForNextLevel*100)}"></b></i></div><h3>ВЛАДЕНИЕ ОРУЖИЕМ</h3><div class="mastery-grid">${Object.entries(s.weaponMastery).map(([key,value])=>`<span>${esc(({pistols:"Пистолеты",smg:"ПП",rifles:"Винтовки",shotguns:"Дробовики",melee:"Ближний бой"})[key])} · ${Math.floor(value)}/100 · ${masteryTier(value)}</span>`).join("")}</div><h3>СЛОТЫ ЭКИПИРОВКИ</h3><div class="gear-select-list">${slots}</div><h3>ДОСТУПНОЕ СНАРЯЖЕНИЕ</h3><div class="gear-select-list">${gear}</div><h3>АРТЕФАКТЫ · ${s.equipment.artifacts.length}/4</h3><div class="gear-select-list">${arts}</div><div class="two-columns"><div><h3>ХАРАКТЕРИСТИКИ</h3><p>Защита: ${pct(s.passive.protection*100)}</p><p>Сопротивление радиации: ${pct(s.passive.radResist*100)}</p><p>Груз: ${s.weight.toFixed(1)} / ${s.stats.maxCarryWeight} кг</p><p>Голод: ${pct(p.hunger)} · жажда: ${pct(p.thirst)} · радиация: ${pct(p.radiation)}</p><p>Уклонение: ${pct((s.passive.evasion||0)*100)} · крит: ${pct((s.passive.critChance||0)*100)}</p><p>Время в Зоне: ${esc(s.timeLabel)}</p></div><div><h3>РЕПУТАЦИЯ</h3>${entries}</div></div>`);}
  function trade(s){const shop=s.shop;if(!shop)return overlay('Здесь нет торговца','<p>В этом секторе не удалось найти безопасный рынок.</p>');const rows=shop.stock.map(x=>`<article class="shop-row">${itemIcon(x.item)}<div class="item-info"><strong>${esc(x.item.name)}</strong><p>${esc(x.item.description)}</p><small>${x.item.weight} кг · цена ${x.price.toLocaleString('ru-RU')} ₽</small></div>${button('buy','Купить','tiny-button',x.id)}</article>`).join('');const owned=s.inventory.filter(x=>{const type=s.items[x.id].type,ref=x.instanceId||x.id,equipped=['primary','sidearm','melee','armor','head','backpack'].some(slot=>s.equipment[slot]===ref)||s.equipment.artifacts.includes(ref);return !equipped&&(!['weapon','armor'].includes(type)||x.id!==s.equipment.weapon&&x.id!==s.equipment.armor);}).map(x=>`<div class="sell-row"><span>${esc(s.items[x.id].name)} ×${x.qty}</span><small>≈ ${Math.round(s.items[x.id].price*.52)} ₽</small>${button('sell','Продать','tiny-button',x.instanceId||x.id)}</div>`).join('')||'<p class="quiet">Нечего продать.</p>';return overlay(`${esc(shop.name)} · торговля`,`<div class="shop-wallet">НАЛИЧНЫЕ <b>₽ ${s.player.money.toLocaleString('ru-RU')}</b> · отношение влияет на цены</div><h3>ПРИЛАВОК</h3><div class="shop-list">${rows}</div><h3>ПРОДАТЬ СВОЁ</h3><div class="sell-list">${owned}</div><h3>ПОРУЧЕНИЯ</h3>${s.quests.available.map(q=>`<div class="sell-row"><span>${esc(q.title)}</span><small>награда ${q.reward} ₽</small>${button('acceptQuest','Взять','tiny-button',q.id)}</div>`).join('')||'<p class="quiet">Поручений нет.</p>'}`);}
  function people(s){const list=s.locations[s.player.location].npcs.filter(id=>window.ZoneRPGZone.npcVisible(s,id)&&(!s.people[id].requiresBackground||s.people[id].requiresBackground===s.backgroundId)&&!s.personalStory.relationships[id]?.dead).map(id=>{const p=s.people[id],shop=s.shop&&s.shop.name===p.name,sprite=p.sprite|| (p.role==='торговец'?'trader':p.role==='медик'?'medic':p.role==='техник'?'technician':p.role==='эколог'||p.role==='исследователь'?'researcher':p.role==='ветеран'||p.role==='военный'?'veteran':p.role==='радист'?'radio':'stalker');let actions=(shop?button('panel','Торговать','tiny-button','trade'):'')+button('npcAction','Поговорить','tiny-button',id+':talk')+(p.nonCombatant?'':button('npcAction','Поручения','tiny-button',id+':quest'))+s.quests.active.filter(q=>q.giver===id&&q.canTurnIn).map(q=>button('turnIn','Сдать задание: '+esc(q.title),'tiny-button',q.id)).join('')+(['враждебный','военный','наёмник'].includes(p.role)?button('npcAction','Напасть','danger-button',id+':fight'):'');return '<article class="person-row"><div class="npc-face"><img src="assets/sprites/npc-'+sprite+'.svg" alt="Портрет: '+esc(p.name)+'"></div><div><strong>'+esc(p.name)+'</strong><small>'+esc(p.species||p.role)+' · '+esc(s.factions[p.faction]?.name||'Зона')+'</small><p>'+esc(p.greeting)+'</p></div><div class="person-actions">'+actions+'</div></article>';}).join('');return overlay('Люди в секторе',list||'<p>Никого поблизости.</p>');}
  function combatItems(s){const rows=s.inventory.filter(x=>['medicine','food','drink'].includes(s.items[x.id].type)).map(x=>button('combat','Использовать '+esc(s.items[x.id].name),'tiny-button',`use:${x.id}`)).join('');return overlay('Предмет в бою',rows||'<p class="quiet">Нет предметов, которые помогут в бою.</p>');}
  function combatWeapons(s){const rows=s.inventory.filter(x=>s.items[x.id].type==='weapon').map(x=>button('combat','Взять '+esc(s.items[x.id].name),'tiny-button',`weapon:${x.id}`)).join('');return overlay('Сменить оружие',rows||'<p class="quiet">В рюкзаке нет другого оружия.</p>');}

  let savePickerOpen=false;
  function setSavePicker(open){savePickerOpen=Boolean(open);}
  function isSavePickerOpen(){return savePickerOpen;}
  function savePicker(s){return overlay('Продолжить игру',(s.loadError?'<p class="panel-intro" role="alert">'+esc(s.loadError)+'</p>':'')+(saveChoices(s)||'<p class="save-absent">Сохранений нет</p>')+button('savePickerBack','Назад','text-button'));}
  function saveChoices(s){
    return (s.saveSlots||[]).map(slot=>{
      const label=slot.type==='auto'?'Автосохранение':'Ручное сохранение';
      const date=slot.savedAt&&Number.isFinite(Date.parse(slot.savedAt))?new Date(slot.savedAt).toLocaleString('ru-RU'):'Время старой записи неизвестно';
      return '<article class="save-card"><b>'+label+'</b><p>'+esc(s.locations[slot.location]?.name||'Неизвестный сектор')+' · Уровень '+esc(slot.level)+' · '+esc(slot.rank)+'</p><small>'+esc(s.backgrounds[slot.background]?.name||'Сталкер')+' · '+esc(date)+'</small>'+button('load','Загрузить · '+label,'secondary-button',slot.type)+'</article>';
    }).join('');
  }
  function death(s){const d=s.deathSummary||{};return `<div class="overlay-shade"><section class="panel-window death-panel" role="dialog" aria-modal="true"><small>СВЯЗЬ ПОТЕРЯНА</small><h1>Ты погиб.</h1><p>Зона оставила твой рюкзак себе. Последнее сохранение не изменено.</p><div class="death-stats"><span>Переходов<b>${d.trips||0}</b></span><span>Побед<b>${d.kills||0}</b></span><span>Артефактов<b>${d.artifacts||0}</b></span><span>Заработано<b>${d.earnings||0} ₽</b></span><span>Заданий<b>${d.quests||0}</b></span></div><div class="scene-actions">${saveChoices(s)}${button('newGame','Начать новую игру','secondary-button')}</div></section></div>`;}
  function settings(s){const toggle=(key,label,description='')=>'<label class="setting-line"><span>'+label+(description?'<small>'+description+'</small>':'')+'</span><select data-setting="'+key+'"><option value="true" '+(s.settings[key]?'selected':'')+'>Да</option><option value="false" '+(!s.settings[key]?'selected':'')+'>Нет</option></select></label>';const slider=(key,label)=>'<label class="setting-line"><span>'+label+'</span><input type="range" min="0" max="1" step="0.01" data-setting="'+key+'" aria-label="'+label+'" value="'+s.settings[key]+'"></label>';return overlay('Настройки','<fieldset class="settings-section"><legend>Игра</legend>'+toggle('tutorialHints','Обучающие подсказки')+toggle('autoTurnInQuests','Автоматически сдавать задания','Только простые поручения рядом с заказчиком; сюжетные диалоги остаются ручными.')+button('resetTutorial','Сбросить подсказки','secondary-button')+'</fieldset><fieldset class="settings-section"><legend>Звук</legend>'+slider('volume','Общая громкость')+slider('musicVolume','Музыка / атмосфера')+slider('effectsVolume','Эффекты')+toggle('music','Включить музыку / атмосферу')+toggle('sfx','Включить эффекты')+toggle('muted','Отключить весь звук')+'</fieldset><fieldset class="settings-section"><legend>Интерфейс</legend>'+toggle('reduceMotion','Уменьшить анимацию')+'<label class="setting-line"><span>Масштаб интерфейса</span><select data-setting="scale"><option value="1" '+(s.settings.scale===1?'selected':'')+'>Обычный</option><option value="1.1" '+(s.settings.scale===1.1?'selected':'')+'>Крупный</option></select></label></fieldset>'+button('deletePrompt','Удалить сохранение','danger-button'));}  function deleteConfirm(){return `<div class="overlay-shade"><section class="panel-window"><header class="panel-window-head"><div><small>ЛОКАЛЬНЫЕ ДАННЫЕ</small><h2>Удалить сохранение?</h2></div>${button('close','×','close-button')}</header><p>Выбери слот для удаления. Второе сохранение останется доступным.</p><div class="scene-actions">${button('deleteSave','Удалить ручное','danger-button','manual')}${button('deleteSave','Удалить автоматическое','danger-button','auto')}${button('close','Отмена','secondary-button')}</div></section></div>`;}
  function menu(s){return '<div class="title-screen"><div class="title-grid"><div class="title-copy"><div class="brand-large">ZONE<span>RPG</span></div><small>ЛОКАЛЬНЫЙ КПК · ВЕРСИЯ '+esc(window.ZoneRPGConfig.version)+'</small><h1>Зона не ждёт.</h1><p>Один переход. Один выбор. Никто не знает, что будет дальше.</p><div class="title-actions">'+button('newGame','Новая игра','primary-button')+(s.hasSave?button('savePicker','Продолжить игру','secondary-button'):'<button class="secondary-button" type="button" data-action="savePicker" disabled>Продолжить игру</button>')+button('panel','Настройки','text-button','settings')+(s.hasSave?'<small>Новая игра сохранит прежние записи до первого нового сохранения. Ручная запись заменяется только вручную.</small>':'')+'</div>'+(s.loadError?'<p class="panel-intro" role="alert">'+esc(s.loadError)+'</p>':'')+'<div class="title-foot">Браузерная игра · Сохранение хранится на этом устройстве · звук запускается после нажатия</div></div><aside class="title-brief"><span>РАДИОКАНАЛ · КОРДОН</span><p>«Ты входишь в Зону. На юге ещё видны огни блокпоста. Сидорович уже ждёт…»</p><div class="brief-readout"><span>РАДИАЦИОННЫЙ ФОН</span><b>04 μSv/h</b></div><div class="brief-readout"><span>СЕВЕРНЫЙ МАРШРУТ</span><b>НЕИЗВЕСТЕН</b></div></aside></div></div>';}  function pausePanel(){return overlay('Пауза',`<p class="panel-intro">Время в Зоне остановлено. Сохранение доступно в разделе «Ещё».</p><div class="menu-actions">${button('resume','Вернуться в игру','primary-button')}${button('panel','Настройки','secondary-button','settings')}${button('home','Главное меню','text-button')}</div>`);}
  function notebook(s){return overlay('Слухи и заметки',s.rumors.length?'<div class="journal-list">'+[...s.rumors].reverse().map(r=>{const d=window.ZoneRPGKnowledge.display(r),loc=window.ZoneRPGWorld.locations[r.location]?.name||(typeof r.location==='string'&&/[А-Яа-яЁё]/.test(r.location)?r.location:'Зона');return '<article class="journal-entry"><b>'+esc(d.title)+'</b><small>'+esc(loc)+' · '+String(r.time??'--').padStart(2,'0')+':00 · глубина '+(r.depth||0)+'</small><p>'+esc(d.text)+'</p></article>';}).join('')+'</div>':'<p class="quiet">Пока пусто. У костра можно послушать дорожные слухи.</p>');}


  function expeditionReport(s){const e=s.lastExpedition;if(!e)return overlay('Итоги вылазки','<p>Ты ещё не вернулся из первой экспедиции.</p>');const t=e.summary;return overlay('Итоги вылазки','<h3>'+esc(s.locations[e.originLocationId].name)+' · глубина '+e.depth+'</h3><p>'+t.hours+' ч · '+t.xp+' XP · '+t.money+' ₽ · '+t.kills+' побед</p><h3>НАЙДЕНО</h3>'+Object.entries(t.items).map(([id,n])=>'<p>+'+n+' '+esc(s.items[id].name)+'</p>').join('')+'<h3>ПОСЛЕДНИЕ ВСТРЕЧИ</h3>'+e.history.map(id=>'<p>'+esc(s.eventDefinitions.find(x=>x.id===id)?.category||'Тихий участок')+'</p>').join(''));}
  function factionPanel(s){return overlay('Группировки','<p>Ваша репутация показывает, как эта группировка относится лично к вам.</p>'+s.factionStatuses.map(f=>'<article class="faction-card"><h3><img class="faction-symbol" src="assets/sprites/faction-'+f.id+'.svg" alt="Символ группировки"> '+esc(f.name)+'</h3><p>'+esc(f.description||'')+'</p><p><b>Ваша репутация: '+(f.rep>0?'+':'')+f.rep+' — '+esc(f.tier)+'</b></p><p>Статус: '+(f.member?'член группировки':'не состоите')+'</p>'+(f.base?'<p>База: '+esc(s.locations[f.base].name)+(f.leader?' · Представитель: '+esc(s.people[f.leader]?.name||f.leader):'')+'</p><p>Для вступления: ранг '+esc(window.ZoneRPGRank.tiers[f.minimumRank][0])+' · уровень '+f.minRank+' · репутация '+f.minRep+'.</p>':'')+'<p>'+esc(f.benefit||'Вступление недоступно.')+'</p>'+(f.member?button('leaveFaction','Покинуть (−15 репутации)','tiny-button'):f.canJoin?button('joinFaction','Вступить','primary-button',f.id):'<small>'+(!f.joinable?'Не принимают участников.':s.factionMembership?'Сначала покинь текущую группировку.':s.playerRank.index<f.minimumRank?'Недостаточный ранг. Требуется: '+esc(window.ZoneRPGRank.tiers[f.minimumRank][0])+'.':'Посети базу и выполни условия.')+'</small>')+'</article>').join(''));}
  function encyclopediaLegacy(s){return overlay('Полевой справочник',window.ZoneRPGZoneUI.knowledge(s,esc,button)+'<h3>Обнаруженные сектора</h3>'+s.known.map(id=>'<article class="journal-entry"><b>'+esc(s.locations[id].name)+'</b><p>'+esc(s.locations[id].description)+'</p></article>').join('')+'<h3>Текущие сводки</h3>'+s.livingView.activeEvents.map(a=>{const d=s.worldEventDefinitions.find(x=>x.id===a.id);return '<article class="journal-entry"><b>'+esc(d.name)+'</b><p>'+esc(d.description)+' · ещё '+Math.ceil(a.endsAt-s.worldClock)+' ч</p></article>';}).join('')+'<h3>Артефакты</h3>'+s.inventory.filter(x=>s.items[x.id].type==='artifact').map(x=>'<article class="journal-entry">'+itemIcon(s.items[x.id])+'<b>'+esc(s.items[x.id].name)+'</b><p>'+esc(itemFacts(s.items[x.id]))+'</p></article>').join('')+'<h3>Встреченные противники</h3>'+s.discoveredEnemies.map(id=>'<article class="journal-entry"><img class="encyclopedia-portrait" src="assets/sprites/enemy-'+s.enemyDefinitions[id].visual+'.svg" alt="'+esc(s.enemyDefinitions[id].name)+'"><b>'+esc(s.enemyDefinitions[id].name)+'</b><p>'+esc(s.enemyDefinitions[id].description)+'</p></article>').join('')+'<h3>Записи</h3>'+s.knowledge.map(x=>{const d=window.ZoneRPGKnowledge.display(x);return '<article class="journal-entry"><b>'+esc(d.title)+'</b><p>'+esc(d.text)+'</p></article>';}).join('')+'<h3>Слухи</h3>'+s.rumors.map(r=>{const d=window.ZoneRPGKnowledge.display(r);return '<article class="journal-entry"><b>'+esc(d.title)+'</b><p>'+esc(d.text)+'</p></article>';}).join(''));}

  const databaseCategories={hub:'Обзор',bestiary:'Бестиарий',artifacts:'Артефакты',locations:'Локации',factions:'Группировки',rumors:'Слухи',legends:'Легенды Зоны',history:'История Зоны',records:'Открытия и записи',places:'Известные места',personal:'Личная история',world:'Обстановка в Зоне'};
  let databaseTab='hub';
  function setDatabaseTab(tab){if(Object.hasOwn(databaseCategories,tab))databaseTab=tab;}
  function panelBody(html){return html.slice(html.indexOf('</header>')+9,html.lastIndexOf('</section>'));}
  function databaseSection(s,title,nextTitle){
    const html=encyclopediaLegacy(s),start=html.indexOf('<h3>'+title+'</h3>');
    if(start<0)return '';
    const end=nextTitle?html.indexOf('<h3>'+nextTitle+'</h3>',start):html.lastIndexOf('</section>');
    return html.slice(start,end<0?html.lastIndexOf('</section>'):end);
  }
  function encyclopedia(s){
    const tabs=Object.entries(databaseCategories).map(([id,label])=>'<button type="button" class="tiny-button database-tab" data-action="databaseTab" data-value="'+id+'" aria-pressed="'+(id===databaseTab)+'">'+label+'</button>').join('');
    let body='';
    switch(databaseTab){
      case'bestiary':body=window.ZoneRPGZoneUI.knowledge(s,esc,button,'mutants')+databaseSection(s,'Встреченные противники','Записи');if(!s.discoveredEnemies.length&&!Object.keys(s.zoneView.knowledge.mutants).length)body+='<p>Противники ещё не встречены. Наблюдения появятся по мере исследования Зоны.</p>';break;
      case'artifacts':body=window.ZoneRPGZoneUI.knowledge(s,esc,button,'artifacts')+databaseSection(s,'Артефакты','Встреченные противники');if(!s.inventory.some(x=>s.items[x.id].type==='artifact')&&!Object.keys(s.zoneView.knowledge.artifacts).length)body+='<p>Пока нет наблюдений об артефактах. Неизвестные находки скрыты.</p>';break;
      case'locations':body=window.ZoneRPGZoneUI.knowledge(s,esc,button,'locations')+databaseSection(s,'Обнаруженные сектора','Текущие сводки');break;
      case'factions':body=panelBody(factionPanel(s));break;
      case'rumors':body=panelBody(notebook(s));break;
      case'legends':body=panelBody(zoneLegends(s));break;
      case'history':body=panelBody(window.ZoneRPGZoneUI.panel({...s,mode:'zoneStory'},esc,button,overlay));break;
      case'places':body=panelBody(window.ZoneRPGZoneUI.panel({...s,mode:'zonePlaces'},esc,button,overlay));break;
      case'personal':body=panelBody(personalStoryPanel(s));break;
      case'world':body=panelBody(worldStatus(s));break;
      case'records':body=databaseSection(s,'Записи','Слухи');if(!s.knowledge.length)body+='<p>Полевые записи появятся после открытий и разговоров.</p>';break;
      default:body='<p>База знаний КПК. Выбери категорию выше. Здесь появляются только уже открытые сведения.</p><p>Секторов: '+s.known.length+' · Противников: '+s.discoveredEnemies.length+' · Записей: '+s.knowledge.length+'</p>';
    }
    return overlay('Энциклопедия Зоны','<nav class="database-tabs" aria-label="Категории энциклопедии">'+tabs+'</nav><section class="database-content" aria-label="'+databaseCategories[databaseTab]+'"><h3>'+databaseCategories[databaseTab]+'</h3>'+body+'</section>'+(databaseTab!=='hub'?button('databaseTab','К обзору базы','secondary-button','hub'):''));
  }
  function profilePanel(s){return overlay('Статистика и достижения','<h3>Статистика</h3>'+panelBody(statisticsPanel(s))+(s.lastExpedition?button('panel','Итоги последней вылазки','secondary-button','expeditionReport'):'')+'<h3>Достижения</h3>'+panelBody(window.ZoneRPGZoneUI.panel({...s,mode:'achievements'},esc,button,overlay)));}
  function worldStatus(s){const v=s.livingView;return overlay('Обстановка в Зоне','<p class="panel-intro">Последние известные сводки. Наблюдения могут устареть; неизвестные секторы здесь не раскрываются.</p><div class="journal-list">'+v.information.map(o=>'<article class="journal-entry"><b>'+esc(o.name)+'</b><p>'+esc(o.state)+'</p><small>'+Math.max(0,Math.floor(s.worldClock-o.time))+' ч назад · '+esc(({visit:'личное наблюдение',radio:'радио',rumor:'местная информация'})[o.source])+'</small></article>').join('')+'</div><h3>ПОЛЕВОЙ КАНАЛ</h3>'+v.news.slice().reverse().map(n=>'<article class="journal-entry"><b>'+esc(n.title)+'</b><p>'+esc(n.text)+'</p></article>').join('')+'<h3>ОТМЕТКИ НА ПОЛЯХ</h3>'+v.chains.map(c=>'<article class="journal-entry"><b>'+esc(c.name)+'</b><p>'+esc(c.clue)+'</p><small>'+(c.step===3?'Запись восстановлена':'Ищи названный ориентир после следующего перехода')+'</small></article>').join(''));}
  function zoneLegends(s){return overlay('Легенды Зоны',s.livingView.legends.length?s.livingView.legends.map(r=>'<article class="journal-entry legend-entry"><b>'+esc(r.title)+'</b><p>'+esc(r.text)+'</p></article>').join(''):'<p class="quiet">Пока записей нет. Не каждая история открывается с ближней тропы.</p>');}
  function statisticsPanel(s){const t=s.livingView.statistics;return overlay('Статистика пути','<div class="path-statistics">'+[['Игровых дней',t.days],['Завершённых вылазок',t.expeditions],['Максимальная глубина',t.maxDepth],['Встреч в вылазках',t.encounters],['Начатых боёв',t.battles],['Побед',s.player.kills],['Найденных артефактов',s.player.artifacts],['Выполненных поручений',s.statistics.quests],['Посещений секторов',t.visits],['Записанных легенд',s.livingView.legends.length]].map(([name,n])=>'<div><span>'+esc(name)+'</span><strong>'+n+'</strong></div>').join('')+'</div><p class="quiet">Подробные счётчики Living Zone начинаются с версии 9. Старый прогресс сохранён.</p>');}
  function creditsPanel(){const c=window.ZoneRPGConfig;return overlay('Авторы','<section class="credits-panel"><h3>ZoneRPG · '+esc(c.version)+'</h3><dl>'+Object.entries({developer:'Разработка',betaTester:'Бета-тестирование',music:'Музыка'}).map(([key,role])=>'<div><dt>'+role+'</dt><dd>'+esc(c.credits[key])+'</dd></div>').join('')+'</dl><p>Спасибо игрокам и тестерам, которые возвращаются в Зону и помогают замечать то, что осталось за кадром.</p></section>');}
  function morePanel(s){return overlay('Ещё',`<p class="panel-intro">Записи и системные действия КПК.</p><div class="menu-actions more-actions">${button('panel','Энциклопедия Зоны','secondary-button','encyclopedia')}${button('panel','Статистика и достижения','secondary-button','statistics')}${button('panel','Настройки','secondary-button','settings')}${button('panel','Авторы','secondary-button','credits')}${button('save','Сохранить','secondary-button')}${button('panel','Пауза','text-button','pause')}</div>`);}
  function storyLocationHint(s){const v=s.storyView;if(v.complete||v.ready||v.location!==s.player.location)return '';return v.cooldown?'<small class="story-cooldown">Личная история · вернись через '+v.cooldown+' ч.</small>':'<button type="button" class="secondary-button story-action" data-action="storyAction" title="'+esc(v.action)+'"'+(s.event||s.combat||s.expedition.active?' disabled':'')+'><span class="story-action-label">Личная история · '+esc(v.action)+'</span></button>';}
  function personalStoryPanel(s){const p=s.personalStory,v=s.storyView,a=s.storyArcs[s.backgroundId],q=s.quests.active.find(q=>q.id===v.questId);const past=p.completedSteps.map(id=>{const n=a.quests.indexOf(id);return '<li>'+esc(a.chapters[n][0])+'</li>';}).join('');const decisions=Object.entries(p.importantChoices).map(([id,key])=>{const n=a.quests.indexOf(id),c=a.chapters[n],label=key==='a'?c[4]:key==='b'?c[5]:'Проверенное решение';return '<li>'+esc(c[0])+': '+esc(label)+'</li>';}).join('');return overlay('Личная история','<div class="story-summary"><small>'+esc(s.backgrounds[s.backgroundId].name)+'</small><h3>'+esc(v.title)+'</h3><p>'+esc(v.theme)+'</p>'+(v.complete?'<h3>Личная история завершена</h3><p>'+esc(v.summary)+'</p><p>Исследование Зоны продолжается. Полевой навык: '+esc(Object.entries(v.perk).map(([key,value])=>({maxWeight:'Грузоподъёмность',evasion:'Уклонение',accuracy:'Точность',artifactFindChance:'Поиск артефактов',healingBonus:'Лечение',radResist:'Радзащита'})[key]+' +'+(key==='maxWeight'?value+' кг':Math.round(value*1000)/10+'%')).join(', '))+'</p>':'<h3>Глава '+v.chapter+' · '+esc(v.chapterTitle)+'</h3><p>'+esc(v.description)+'</p><p>Отметка: '+esc(s.locations[v.location].name)+'</p>'+(q?'<p>'+esc(q.status)+' · Отчёт: '+esc(s.people[q.giver].name)+' — '+esc(s.locations[q.turnInLocations[0]].name)+'</p>':'<p>Поговори со знакомыми или проверь отметку. Поручение можно принять при встрече.</p>')+(v.cooldown?'<p>До следующей встречи: '+v.cooldown+' ч. Обычная игра остаётся доступной.</p>':''))+'</div>'+storyLocationHint(s)+(p.pendingRewards.length?'<p>Награда ждёт места в рюкзаке.</p>'+(s.event||s.combat?disabledButton('Забрать личную награду','Сначала завершите встречу'):button('claimStoryRewards','Забрать личную награду','secondary-button')):'')+'<h3>Важные решения</h3><ul class="story-decisions">'+(decisions||'<li>Решений пока нет.</li>')+'</ul><h3>Завершённые главы</h3><ol>'+past+'</ol><h3>Знакомые</h3>'+p.relatedNPCs.map(id=>{const npc=s.people[id],r=p.relationships[id];return '<article class="story-person"><img src="assets/sprites/npc-'+npc.sprite+'.svg" alt="'+esc(npc.name)+'"><div><b>'+esc(npc.name)+'</b><p>'+esc(npc.storyRole)+' · '+esc(s.locations[npc.home].name)+'</p><small>'+(r?.dead?'Погиб':r?.ally?'Союзник':r?.trust<0?'Недоверие':'Нейтрально')+'</small></div></article>';}).join('')+'<h3>Записи истории</h3>'+p.log.map(x=>'<p>'+esc(x)+'</p>').join(''));}
  function backgroundPanel(s){return overlay('Прошлое сталкера','<p class="panel-intro">Предыстория определяет прошлое, первые вещи и личную историю. Дальнейший путь зависит от твоих решений.</p><div class="background-grid">'+Object.entries(s.backgrounds).map(([id,b])=>'<article class="background-card"><img class="background-portrait" src="assets/sprites/background-'+esc(id)+'.svg" alt="'+esc(b.name)+'"><h3>'+esc(b.name)+'</h3><p class="background-playstyle">'+esc(({rookie:'Свободный путь · развитие на свой выбор',soldier:'Боевая подготовка · запас боеприпасов',technician:'Механизмы и поиск · технические решения',hunter:'Следы и ближний бой · чутьё',scavenger:'Груз и обмен · связи на Свалке',medic:'Помощь и выживание · лечение'})[id])+'</p><p>'+esc(b.description)+'</p><p class="story-theme">Личная история: '+esc(s.storyArcs[id].theme)+'</p><small>Старт: '+esc(s.locations[b.startLocation].name)+' · '+(Object.entries(b.reputation||{}).map(([id,n])=>esc(s.factions[id].name)+' '+(n>0?'+':'')+n).join(', ')||'нейтральная репутация')+'</small>'+button('startGame','Начать · '+esc(b.name),'primary-button',id)+'</article>').join('')+'</div>');}
  function panelFor(s){const zonePanel=window.ZoneRPGZoneUI.panel(s,esc,button,overlay);if(zonePanel)return zonePanel;switch(s.mode){case'credits':return creditsPanel();case'worldStatus':return worldStatus(s);case'zoneLegends':return zoneLegends(s);case'statistics':return profilePanel(s);case'personalStory':return personalStoryPanel(s);case'background':return backgroundPanel(s);case'menu':return menu(s);case'dead':return death(s);case'pause':return pausePanel();case'expeditionReport':return expeditionReport(s);case'factions':return factionPanel(s);case'encyclopedia':return encyclopedia(s);case'more':return morePanel(s);case'settings':return settings(s);case'deleteConfirm':return deleteConfirm();case'inventory':return inventory(s);case'map':return mapPanel(s);case'quests':return questsPanel(s);case'character':return character(s);case'trade':return trade(s);case'people':return people(s);case'notebook':return notebook(s);case'combatItems':return combatItems(s);case'combatWeapons':return combatWeapons(s);default:return '';}}
  let lastFeedback=0,lastFeedbackAt=-Infinity;
  function tutorialCard(s){if(!s.settings.tutorialHints||!['play','event','combat'].includes(s.mode))return '';const id=s.tutorial.queue[0],hint=window.ZoneRPGOnboarding.hints[id];if(!hint)return '';return '<aside class="tutorial-card" aria-label="Обучающая подсказка"><small>ПОДСКАЗКА КПК</small><h3>'+esc(hint[0])+'</h3><p>'+esc(hint[1])+'</p>'+button('dismissHint','Понятно','tiny-button')+'</aside>';}

  const survivalRules=[
    ['health','здоровье критически низкое',s=>s.player.health<=s.stats.maxHealth*.35],
    ['stamina','выносливость на исходе',s=>s.player.stamina<=s.stats.maxStamina*.2],
    ['radiation','уровень радиации опасно высокий',s=>s.player.radiation>=65],
    ['hunger','сильный голод',s=>s.player.hunger>=80],
    ['thirst','сильная жажда',s=>s.player.thirst>=80]
  ];
  const survivalFlags={};
  let survivalText='',survivalUntil=-Infinity,toastUntil=-Infinity,toastTimer=null;
  function updateSurvivalAlerts(s,now=performance.now()){
    if(['menu','background','dead'].includes(s.mode)){survivalText='';survivalUntil=-Infinity;return '';}
    let crossed=false;
    const active=[];
    for(const [key,label,critical]of survivalRules){
      const danger=critical(s);
      if(danger){active.push(label);if(!survivalFlags[key])crossed=true;}
      survivalFlags[key]=danger;
    }
    if(crossed)survivalUntil=now+4500;
    if(!active.length)survivalUntil=-Infinity;
    survivalText=active.length?'⚠ Внимание: '+active.join('; ')+'.':'';
    return now<survivalUntil?survivalText:'';
  }
  function rewardToast(s){
    const now=performance.now(),warning=updateSurvivalAlerts(s,now);
    if(!s.feedback){lastFeedback=0;lastFeedbackAt=-Infinity;}
    else if(s.feedback.serial!==lastFeedback){lastFeedback=s.feedback.serial;lastFeedbackAt=now;}
    const reward=s.feedback&&now-lastFeedbackAt<=3200?s.feedback.text:'';
    toastUntil=Math.max(warning?survivalUntil:-Infinity,reward?lastFeedbackAt+3200:-Infinity);
    if(!warning&&!reward)return '';
    // One shared toast: simultaneous warnings and rewards never overlap.
    return '<div class="reward-toast'+(warning?' survival-warning':'')+'" role="status">'+
      esc(warning||reward)+(warning&&reward?'<small>'+esc(reward)+'</small>':'')+'</div>';
  }
  function bindToastExpiry(){
    if(toastTimer!==null)clearTimeout(toastTimer);
    toastTimer=null;
    const toast=root.querySelector?.('.reward-toast'),remaining=toastUntil-performance.now();
    if(toast&&remaining>0)toastTimer=setTimeout(()=>{toast.remove?.();toastTimer=null;},remaining);
  }

  let mapObserver=null,mapResizeCleanup=null;
  // SVG uses a stretched 100 x 100 viewBox. Convert measured border-box
  // centers from viewport coordinates into that same SVG coordinate space.
  function updateMapLines(map){
    const svg=map.querySelector('svg');
    if(!svg)return;
    const bounds=svg.getBoundingClientRect();
    if(!bounds.width||!bounds.height)return;
    const nodes=new Map(Array.from(map.querySelectorAll('.map-node')).map(node=>[node.dataset.value,node.getBoundingClientRect()]));
    for(const line of map.querySelectorAll('.map-path')){
      const from=nodes.get(line.dataset.from),to=nodes.get(line.dataset.to);
      if(!from||!to)continue;
      const a={x:from.left+from.width/2,y:from.top+from.height/2};
      const b={x:to.left+to.width/2,y:to.top+to.height/2};
      let end=b;
      // Keep directed arrowheads visible at the target's border, on the
      // center-to-center ray; ordinary lines run behind the button center.
      if(line.hasAttribute('marker-end')){
        const dx=a.x-b.x,dy=a.y-b.y;
        const factor=Math.min(dx?to.width/2/Math.abs(dx):Infinity,dy?to.height/2/Math.abs(dy):Infinity);
        if(Number.isFinite(factor)&&factor<1)end={x:b.x+dx*factor,y:b.y+dy*factor};
      }
      line.setAttribute('x1',(a.x-bounds.left)/bounds.width*100);
      line.setAttribute('y1',(a.y-bounds.top)/bounds.height*100);
      line.setAttribute('x2',(end.x-bounds.left)/bounds.width*100);
      line.setAttribute('y2',(end.y-bounds.top)/bounds.height*100);
    }
  }

  function centerMapGraph(map){
    const content=map.querySelector('.map-content');
    if(!content?.style)return;
    // Reset before measuring: repeated resize callbacks cannot accumulate drift.
    content.style.transform='none';
    const rects=Array.from(map.querySelectorAll('.map-node')).map(n=>n.getBoundingClientRect());
    if(!rects.length)return;
    const viewport=map.getBoundingClientRect(),origin=content.getBoundingClientRect();
    const width=map.clientWidth,height=map.clientHeight,padding=12;
    if(!width||!height)return;
    const minX=Math.min(...rects.map(r=>r.left)),maxX=Math.max(...rects.map(r=>r.right));
    const minY=Math.min(...rects.map(r=>r.top)),maxY=Math.max(...rects.map(r=>r.bottom));
    const scale=Math.min(1,Math.max(1,width-2*padding)/(maxX-minX||1),Math.max(1,height-2*padding)/(maxY-minY||1));
    const targetX=viewport.left+map.clientLeft+width/2,targetY=viewport.top+map.clientTop+height/2;
    const x=targetX-(origin.left+((minX+maxX)/2-origin.left)*scale);
    const y=targetY-(origin.top+((minY+maxY)/2-origin.top)*scale);
    content.style.transform='translate('+x+'px,'+y+'px) scale('+scale+')';
  }
  function updateMapLayout(map){centerMapGraph(map);updateMapLines(map);}
  function bindMapLines(){
    mapObserver?.disconnect();mapObserver=null;
    mapResizeCleanup?.();mapResizeCleanup=null;
    const map=root.querySelector?.('.zone-map');
    if(!map)return;
    updateMapLayout(map);
    if(window.ResizeObserver){
      mapObserver=new window.ResizeObserver(()=>updateMapLayout(map));
      mapObserver.observe(map);
      for(const node of map.querySelectorAll('.map-node'))mapObserver.observe(node);
    }else if(window.addEventListener){
      const resize=()=>updateMapLines(map);
      window.addEventListener('resize',resize);
      mapResizeCleanup=()=>window.removeEventListener('resize',resize);
    }
  }
  function render(s){if(s.mode!=='menu')savePickerOpen=false;document.documentElement.style.setProperty('--ui-scale',s.settings.scale);document.body.dataset.motion=s.settings.reduceMotion?'reduced':'full';document.body.dataset.hp=s.player.health<=s.stats.maxHealth*.15?'critical':s.player.health<=s.stats.maxHealth*.35?'low':'safe';document.body.dataset.rad=s.player.radiation>=65?'high':s.player.radiation>=30?'warning':'safe';document.body.dataset.hunger=s.player.hunger>=80?'high':'safe';document.body.dataset.thirst=s.player.thirst>=80?'high':'safe';document.body.dataset.overweight=s.weight>s.capacity?'true':'false';document.body.dataset.eventRare=s.event&&['rare','very_rare','special','unique'].includes(s.event.rarity)?'true':'false';window.ZoneRPGAudio?.sync(s.mode,s.settings,{combat:Boolean(s.combat),expedition:s.expedition.active,factionBase:s.factionStatuses.some(f=>f.base===s.player.location),depth:s.expedition.depth,night:s.player.time<5||s.player.time>=21,danger:s.locations[s.player.location].danger,legendary:s.event?.rarity==='legendary',climax:s.zoneView.stage>=17&&!s.zoneView.ending,location:s.player.location,underground:['underground','southTunnel'].includes(s.player.location),forest:['wild','redforest','rookie'].includes(s.player.location),industrial:['garbage','railway','machineYard','militaryDepot'].includes(s.player.location)});root.innerHTML=(s.mode==='menu'?menu(s)+(savePickerOpen?savePicker(s):''):s.mode==='dead'?gameScreen(s)+death(s):gameScreen(s)+panelFor(s))+rewardToast(s);root.dataset.mode=s.mode;bindMapLines();bindToastExpiry();}
  window.ZoneRPGUI={render,updateMapLines,centerMapGraph,setDatabaseTab,updateSurvivalAlerts,setSavePicker,isSavePickerOpen};
})();
